(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.04-t*0.5)*5 + Math.cos(y*0.035+t*0.4)*4;
  const w2y = Math.cos(y*0.04+t*0.45)*5 + Math.sin(x*0.038-t*0.55)*4;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.15],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.12],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.18],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.10],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.14],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.16],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.11],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.085, 1.8, 0.13],
    [200+Math.sin(t*0.38+1)*110, 180+Math.cos(t*0.58+3)*70, 0.075, 2.4, 0.17]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const decay = 1.0/(1.0+d*0.003);
    aS += (Math.sin(d*f - t*sp) + Math.sin(d*f*2.3 - t*sp*1.7)*0.3)*w*decay;
    iS += (Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) + Math.cos(d*f*1.5 + t*sp*0.4)*0.3)*w*decay;
    cS += Math.sin(d*f*1.8 - t*sp*0.8 + 2.0)*w*decay*0.5;
  }
  const act = aS/1.26, inh = iS/1.26, cross = cS/0.63;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2 + Math.sin(sx*0.08+sy*0.06-t*1.8)*0.15 + Math.sin(sx*0.02-sy*0.03+t*0.6)*0.25;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
