  const moire = (grid1 + grid2)*0.5;
  const raw = act - inh*0.65 + bg*0.25 + spiral*0.4 + cross*0.2 + moire*0.15;
  const reaction = Math.tanh(raw*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5 + Math.sin(sx*0.22-sy*0.18+t*1.3)*0.3)*1.5)*0.3;
  const detail = Math.sin(sx*0.3+sy*0.25+t*3)*Math.sin(sx*0.2-sy*0.3-t*2.5)*0.15;
  const blend = reaction*0.65 + cell*0.2 + detail*0.15;
  const v = blend*0.5+0.5;
  const pal = [[6,12,52],[12,42,88],[18,85,120],[25,140,135],[60,175,150],[180,195,80],[220,170,60],[215,120,70],[185,75,80],[140,45,75],[80,25,60],[35,15,48],[6,12,52]];
